// What the Capture and Timer controls run (Control Center, the Action
// button): open Task at a place.
//
// Compiled into BOTH the app (apps/mobile/ios/TaskLive, linked into the
// Rust binary, its App Intents metadata generated by apps/mobile/build.rs)
// and the widget extension (apps/ios-widgets). A control cannot open the
// app with a custom-scheme link from the extension — `OpenURLIntent` only
// honours universal links there, and the button shows its glyph and does
// nothing — so the intent asks to run in the app instead
// (`openAppWhenRun`). The system brings Task forward and runs `perform`
// in the app's process, where opening our own link reaches the app's URL
// handler (`ui::deep_link`) like any widget tap. That needs the app to
// declare the same intent, hence both targets.

import AppIntents
import Foundation
#if TASK_APP
import UIKit
#endif

@available(iOS 18.0, *)
struct OpenTaskIntent: AppIntent {
    static let title: LocalizedStringResource = "Open Task"
    static let isDiscoverable = false
    static let openAppWhenRun = true

    @Parameter(title: "Place") var place: String

    init() {}
    init(_ place: String) { self.place = place }

    @MainActor
    func perform() async throws -> some IntentResult {
        #if TASK_APP
        if let url = URL(string: "app.fasttrackstudio.task://\(place)") {
            await UIApplication.shared.open(url)
        }
        #endif
        return .result()
    }
}
